   "enunciado": "Un paciente ingresado en el Servicio de Traumatología tras haber sufrido de una fractura de pelvis hace 3 días, de forma repentina disnea y dolor torácico. Entre sus antecedentes personales más importantes están la obesidad así como ser fumador importante. TA 120 / 60, pulso arterial 100 lpm, 28 respiraciones por minuto, saturación de oxigeno 91 % respirando aire ambiente. El resto de la analítica es normal. La radiografía de tórax es normal. Nos encontramos posiblemente ante una caso de:",
